export function newChapterState(){return{revision:3,chapterState:{chapter1:0},missions:{},currentMission:null,gangMoney:2,unlockedContacts:[],unlockedVehicles:[],unlockedLocations:['bank','home'],world:{control:0,nodes:{},damage:{},rescued:[],hq:false,mapUpgraded:false,night:false},chapterComplete:false};}
export class MissionManager{
  constructor(definitions,host,state,options={}){this.definitions=definitions;this.host=host;this.state=state||newChapterState();this.objectiveKey=null;this.options={chapterKey:'chapter1',finalStage:7,...options};}
  get mission(){return this.definitions.find(m=>m.id===this.state.currentMission);}
  get record(){return this.mission?this.state.missions[this.mission.id]:null;}
  get objective(){return this.mission?.objectives[this.record.currentObjective];}
  begin(){if(this.state.chapterComplete){this.host.world(this.state);return;}if(!this.mission)this.startNext();else{this.host.world(this.state);this.activate(true);}}
  startNext(){const m=this.definitions.find(m=>this.state.missions[m.id]?.status!=='completed'&&m.prerequisites.every(id=>this.state.missions[id]?.status==='completed'));if(!m)return;this.state.currentMission=m.id;this.state.missions[m.id]||={status:'active',currentObjective:0,progress:{},attempts:0};this.state.missions[m.id].status='active';this.state.chapterState[this.options.chapterKey]=m.stage;Object.assign(this.state.world,m.onStart||{});this.host.world(this.state);this.host.banner('MISSION STARTED',m.title);this.host.dialogue(m.id+':start',m.dialogues,'电话');this.activate();}
  activate(restoring=false){if(!this.objective)return;this.record.currentObjectiveId=this.objective.id;this.objectiveKey=this.objective.id;this.host.objective(this.objective,this.record.progress,restoring);this.host.hud(this.mission,this.objective,this.record);this.host.save();}
  event(type,payload={}){if(!this.mission||this.record.status!=='active')return;this.host.event?.(type,payload,this.objective,this.record.progress);}
  tick(dt){if(!this.mission||this.record.status!=='active')return;const result=this.host.evaluate(this.objective,this.record.progress,dt);if(result?.fail)this.fail(result.fail);else if(result===true)this.advance();else this.host.hud(this.mission,this.objective,this.record);}
  advance(){const m=this.mission,o=this.objective;if(!m||this.record.status!=='active')return;this.host.finishObjective?.(o,this.record.progress);this.host.dialogue(this.objectiveKey+':done',o.intro?[]:o.dialogues,o.channel||'无线电');this.record.currentObjective++;this.record.progress={};if(this.record.currentObjective<m.objectives.length){this.activate();return;}this.record.status='completed';for(const [k,v] of Object.entries(m.worldStateChanges||{}))this.state.world[k]=v;for(const k of ['unlockedContacts','unlockedVehicles','unlockedLocations'])for(const v of m.rewards?.[k]||[])if(!this.state[k].includes(v))this.state[k].push(v);this.state.gangMoney+=m.rewards?.gangMoney||0;this.host.reward?.(m.rewards||{});this.host.banner('MISSION PASSED',m.title);this.host.dialogue(m.id+':end',m.completion,'无线电');this.host.world(this.state);if(m.final){this.state.chapterState[this.options.chapterKey]=this.options.finalStage;this.state.chapterComplete=true;this.state.currentMission=null;if(this.options.chapterKey==='chapter1'){this.state.gangMoney=20002;Object.assign(this.state.world,{control:100,hq:true,night:false});}this.host.complete(this.state);}else{this.state.currentMission=null;this.host.deferNext();}this.host.save();}
  fail(reason){if(!this.record||this.record.status!=='active')return;this.record.status='failed';this.record.attempts++;this.record.failure=reason;this.host.fail(reason);this.host.save();}
  retry(){if(!this.record)return;this.record.status='active';this.record.failure=null;this.record.progress={};this.host.reset(this.objective);this.activate();}
  serialize(){return structuredClone(this.state);}
}
